import{_ as a,c as r,o as t,al as o}from"./chunks/framework.CT7RwC5a.js";const m=JSON.parse('{"title":"IMU, AHRS та INS","description":"","frontmatter":{},"headers":[],"relativePath":"uk/sensor/inertial_navigation_systems.md","filePath":"uk/sensor/inertial_navigation_systems.md"}'),i={name:"uk/sensor/inertial_navigation_systems.md"};function s(n,e,l,h,c,d){return t(),r("div",null,e[0]||(e[0]=[o('<h1 id="imu-ahrs-та-ins" tabindex="-1">IMU, AHRS та INS <a class="header-anchor" href="#imu-ahrs-та-ins" aria-label="Permalink to &quot;IMU, AHRS та INS&quot;">​</a></h1><p>PX4 зазвичай працює на контролерах польоту, які включають в себе ІВП, такі як серія Pixhawk, і об&#39;єднує дані датчиків разом із інформацією ССН (супутникова система навігації) в оцінювачі EKF2 для визначення орієнтації, напрямку, позиції та швидкості транспортного засобу.</p><p>However PX4 can also use some INS devices as either sources of raw data, or as an external estimator, replacing EKF2.</p><h2 id="supported-ins-systems" tabindex="-1">Supported INS Systems <a class="header-anchor" href="#supported-ins-systems" aria-label="Permalink to &quot;Supported INS Systems&quot;">​</a></h2><p>INS systems that can be used as a replacement for EKF2 in PX4:</p><ul><li><a href="./../sensor/inertiallabs.html">InertialLabs</a></li><li><a href="./../sensor/vectornav.html">VectorNav</a>: ІВП/AHRS, ССН/INS, Dual GNSS/INS системи, котрі можуть бути використані як зовнішній INS, або джерело вхідної інформації датчиків.</li></ul><h2 id="px4-firmware" tabindex="-1">PX4 Firmware <a class="header-anchor" href="#px4-firmware" aria-label="Permalink to &quot;PX4 Firmware&quot;">​</a></h2><p>The driver module for your INS system may not be included in the PX4 firmware for your flight controller by default.</p><p>You can check by searching the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v6c/default.px4board#L25" target="_blank" rel="noreferrer">default.px4board</a> configuration file for your target board for either:</p><ul><li><code>CONFIG_COMMON_INS</code>, which includes drivers for <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/drivers/ins/Kconfig" target="_blank" rel="noreferrer">all INS systems</a>.</li><li>The key for the particular INS system you are using, such as: <ul><li><code>CONFIG_DRIVERS_INS_ILABS</code></li><li><code>CONFIG_DRIVERS_INS_MICROSTRAIN</code></li><li><code>CONFIG_DRIVERS_INS_VECTORNAV</code></li></ul></li></ul><p>If the required key is not present you can include the module in firmware by adding the key to the <code>default.px4board</code> file, or using the <a href="./../hardware/porting_guide_config.html#px4-board-configuration-kconfig">kconfig board configuration tool</a> and then select the driver you want (<code>Drivers -&gt; INS</code>). Note that if you&#39;re working on a flight controller where flash memory is limited, you&#39;re better off installing just the modules you need.</p><p>You will then need to rebuild the firmware.</p><h2 id="словник" tabindex="-1">Словник <a class="header-anchor" href="#словник" aria-label="Permalink to &quot;Словник&quot;">​</a></h2><h3 id="інерціинии-вимірювальнии-пристріи-івп" tabindex="-1">Інерційний вимірювальний пристрій (ІВП) <a class="header-anchor" href="#інерціинии-вимірювальнии-пристріи-івп" aria-label="Permalink to &quot;Інерційний вимірювальний пристрій (ІВП)&quot;">​</a></h3><p>An IMU is a device that contains a 3-axis accelerometer (motion sensor), 3-axis gyroscope (rotation sensor), and sometimes a magnetometer (compass). The gyroscope and accelerometer provide raw sensor data that allow measurement of a system&#39;s angular rate and acceleration. Магнетометр, якщо він є, надає дані сенсора, які можуть бути використані для визначення напрямку, в якому рухається транспортний засіб.</p><h3 id="система-посилки-заголовку-орієнтаціі-ahrs" tabindex="-1">Система посилки заголовку орієнтації (AHRS) <a class="header-anchor" href="#система-посилки-заголовку-орієнтаціі-ahrs" aria-label="Permalink to &quot;Система посилки заголовку орієнтації (AHRS)&quot;">​</a></h3><p>Система AHRS, яка включає як ІВП, так і систему обробки, яка може надавати інформацію про положення та напрямок на увагу з первинних даних ІВП.</p><h3 id="система-інерціальноі-навігаціі-ins" tabindex="-1">Система інерціальної навігації (INS) <a class="header-anchor" href="#система-інерціальноі-навігаціі-ins" aria-label="Permalink to &quot;Система інерціальної навігації (INS)&quot;">​</a></h3><p>INS є навігаційним пристроєм, який використовує акселерометри, гіроскопи, можливо, магнітометри та комп&#39;ютер для розрахунку положення, швидкості та швидкості руху об&#39;єкта без необхідності зовнішніх посилань. Фактично це AHRS, який також включає оцінку положення/швидкості.</p><h2 id="подальша-інформація" tabindex="-1">Подальша інформація <a class="header-anchor" href="#подальша-інформація" aria-label="Permalink to &quot;Подальша інформація&quot;">​</a></h2><ul><li><a href="https://www.vectornav.com/resources/inertial-navigation-articles/what-is-an-ins" target="_blank" rel="noreferrer">Що таке інерційна навігаційна система?</a> (VectorNav)</li><li><a href="https://www.vectornav.com/resources/inertial-navigation-primer" target="_blank" rel="noreferrer">Посібник з інерціальної навігації</a> (VectorNav)</li></ul>',21)]))}const f=a(i,[["render",s]]);export{m as __pageData,f as default};
